      const matchingPersonIds = [...reasons.keys()].sort(), labels = unique([...reasons.values()].flatMap(value => [...value])).map(reason => reason === 'matching-email' ? 'exact normalized email' : 'exact normalized profile URL'), suggested = matchingPersonIds.length === 1 ? matchingPersonIds[0] : null
